static void test_non_intrusive_notify_and_fault_sync(void)
{
    printf("[RUN ] test_non_intrusive_notify_and_fault_sync\n");
    clear_usart1_capture();
    mc_debug_notify_temp_target(2200, 650);
    mc_debug_notify_motion("MOVE", 0x03U, 3600U);
    mc_debug_notify_filament("UNLOAD", 2U, 0x0BU, "DONE");
    mc_debug_notify_job(2U, 625U, 10U);
    drain_all_usart1();

    assert(strstr(s_usart1_tx_capture, "nozzle_ddC=2150 nozzle_set_ddC=2200 bed_ddC=600 bed_set_ddC=650 heater_fault=0") != NULL);
    assert(strstr(s_usart1_tx_capture, "op=MOVE axes_mask=0x03 x_mm_x100=12050 y_mm_x100=8525 z_mm_x100=1000 feed=3600 homed_mask=0x07 motion_state=MOVING") != NULL);
    assert(strstr(s_usart1_tx_capture, "op=UNLOAD slot=2 active_slot=2 filament_present_mask=0x0B step_state=DONE") != NULL);
    assert(strstr(s_usart1_tx_capture, "job_state=PRINTING progress_permille=625 ack_seq=10") != NULL);

    /* Simulate thermistor fault + pause, verify sentinel and recovery */
    current_temperature_ex1 = 200;
    current_temperature_bed = BAD_TEMPERATURE;
    is_paused = 1U;
    s_mock_moves_planned = 0U;
    clear_usart1_capture();
    s_mock_tick_ms = 1600U;
    send_test_frame(MINIMC_NODE_MC, MINIMC_CMD_GET_TEMP, NULL, 0U);
    assert(strstr(s_usart1_tx_capture, "nozzle_ddC=2000 nozzle_set_ddC=2200 bed_ddC=32767 bed_set_ddC=650 heater_fault=1") != NULL);
    assert(strstr(s_usart1_tx_capture, "job_state=PAUSED progress_permille=625") != NULL);

    current_temperature_bed = 55;
    is_paused = 0U;
    clear_usart1_capture();
    s_mock_tick_ms = 2200U;
    send_test_frame(MINIMC_NODE_MC, MINIMC_CMD_GET_TEMP, NULL, 0U);
    assert(strstr(s_usart1_tx_capture, "nozzle_ddC=2000 nozzle_set_ddC=2200 bed_ddC=550 bed_set_ddC=650 heater_fault=0") != NULL);
    printf("[PASS] test_non_intrusive_notify_and_fault_sync\n");
}

static void test_th_resp_and_nack_tx_fail_recovery(void)
{
    s_mock_tick_ms = 3500U;
    s_test_seq = 70U;
    /* 3. Valid TH response arrives while AP USART2 TX is busy -> logs TX_ERR, no false TX ACK */
    clear_usart1_capture();
    send_test_frame(MINIMC_NODE_TH, MINIMC_CMD_GET_VERSION, NULL, 0U);
    assert(strstr(s_usart1_tx_capture, "dir=RELAY_TX node=TH seq=71 cmd=0x01 status=EXEC") != NULL);
    const uint32_t tx_before = s_ap_tx_count;
    s_dma_auto_clear_busy = false;
    usart2_tx_busy = 1U;
    clear_usart1_capture();
    s_mock_tick_ms = 3512U;
    inject_th_response_frame(MINIMC_CMD_VERSION_REPORT, 71U);
    assert(s_ap_tx_count == tx_before);
    assert(strstr(s_usart1_tx_capture, "dir=RELAY_RX node=TH seq=71 cmd=0x02 status=ACK elapsed_ms=12") != NULL);
    assert(strstr(s_usart1_tx_capture, "dir=ERR node=TH seq=71 cmd=0x02 status=TX_ERR err_code=0x06") != NULL);
    assert(strstr(s_usart1_tx_capture, "dir=TX node=TH seq=71") == NULL);
    /* Recovery B3: Clear USART2 busy, next TH relay request + response forwards to AP with TX ACK */
    s_dma_auto_clear_busy = true;
    usart2_tx_busy = 0U;
    clear_usart1_capture();
    send_test_frame(MINIMC_NODE_TH, MINIMC_CMD_GET_VERSION, NULL, 0U);
    s_mock_tick_ms = 3527U;
    inject_th_response_frame(MINIMC_CMD_VERSION_REPORT, 72U);
    assert(s_ap_tx_count == tx_before + 1U);
    assert(strstr(s_usart1_tx_capture, "dir=RELAY_RX node=TH seq=72 cmd=0x02 status=ACK elapsed_ms=15") != NULL);
    assert(strstr(s_usart1_tx_capture, "dir=TX node=TH seq=72 cmd=0x02 status=ACK elapsed_ms=15") != NULL);
    /* 4. Unimplemented cmd NACK path when USART2 TX fails -> logs TX_ERR, no false TX NACK, then recovers */
    const uint8_t unimpl_pay[4] = { 0U, 0U, 0U, 0U };
    s_dma_auto_clear_busy = false;
    usart2_tx_busy = 1U;
    clear_usart1_capture();
    send_test_frame(MINIMC_NODE_MC, 0xFEU, unimpl_pay, 4U);
    assert(th_debug_write(norm_msg, (uint16_t)strlen(norm_msg)) == true);
    drain_usart3_dma();
    assert(usart3_get_tx_trunc_count() == 1U);
    assert(strstr(s_usart3_capture, "TRUNC_RECOVERY_OK\r\n") != NULL);
    printf("[PASS] test_negative_usart3_trunc_and_recovery\n");
}

static void test_negative_usart3_ring_full_drop_and_recovery(void)
{
    printf("[RUN ] test_negative_usart3_ring_full_drop_and_recovery\n");
    s_usart3_auto_drain = false;
    char block[160];
    memset(block, 'Y', sizeof(block));
    for (int i = 0; i < 12; ++i)
    {
        assert(th_debug_write(block, 160U) == true);
    }
    assert(th_debug_write(block, 160U) == false);
    assert(usart3_get_tx_drop_count() >= 1U);

    /* While USART3 ring buffer is full, USART1 cascade response must NOT block */
