    {
        return false;
    }
    const bool is_truncated = (len > MC_DBG_LINE_MAX_LEN);
    const uint16_t write_len = is_truncated ? MC_DBG_LINE_MAX_LEN : len;
    if (mc_dbg_ring_free_space() < write_len)
    {
        s_mc_dbg_drop_count++;
        return false;
    }
    if (is_truncated)
    {
        s_mc_dbg_trunc_count++;
        mc_dbg_ring_push_bytes(buf, (uint16_t)(MC_DBG_LINE_MAX_LEN - 5U));
        mc_dbg_ring_push_bytes("...\r\n", 5U);
        return true;
    }
    mc_dbg_ring_push_bytes(buf, len);
    return true;
}

void mc_debug_poll_drain(void)
{
    uint16_t budget = MC_DBG_DRAIN_BUDGET;
    while ((budget > 0U) && (s_mc_dbg_tail != s_mc_dbg_head))
    {
        if (usart_flag_get(USART1, USART_TDBE_FLAG) == RESET)
        {
            break;
        }
        const uint8_t byte_val = s_mc_dbg_ring[s_mc_dbg_tail];
        s_mc_dbg_tail = (uint16_t)((s_mc_dbg_tail + 1U) % MC_DBG_RING_CAPACITY);
        usart_data_transmit(USART1, (uint16_t)byte_val);
        budget--;
    }
}

