  if (usart3_tx_free_space() < req_len)
  {
    usart3_tx_drop_count++;
    return false;
  }
  if (!is_truncated)
  {
    return (USART3_write((const uint8_t *)buf, len) == (int)len);
  }
  char trunc_buf[TH_DBG_LINE_MAX_LEN];
  memcpy(trunc_buf, buf, TH_DBG_LINE_MAX_LEN - 5U);
  memcpy(&trunc_buf[TH_DBG_LINE_MAX_LEN - 5U], "...\r\n", 5U);
  usart3_tx_trunc_count++;
  return (USART3_write((const uint8_t *)trunc_buf, TH_DBG_LINE_MAX_LEN) == (int)TH_DBG_LINE_MAX_LEN);
}

