static void usart3_ring_push_bytes(const uint8_t *data, uint16_t write_len)
{
  const uint16_t head = usart3_tx_head;
  uint16_t first_chunk = (uint16_t)(USART3_TXBUFF_SIZE - head);
  if (first_chunk > write_len)
  {
    first_chunk = write_len;
  }
  const uint16_t second_chunk = (uint16_t)(write_len - first_chunk);

  memcpy(&usart3_tx_buffer[head], data, first_chunk);
  if (second_chunk > 0U)
  {
    memcpy(&usart3_tx_buffer[0], &data[first_chunk], second_chunk);
  }
  usart3_tx_head = (uint16_t)((head + write_len) % USART3_TXBUFF_SIZE);
  usart3_dma_tx_kick();
}

int USART3_write(const uint8_t *data, uint16_t len)
{
  if ((data == NULL) || (len == 0U))
  {
    return 0;
  }
  usart_enter_critical();
  const uint16_t free_space = usart3_tx_free_space();
  uint16_t write_len = len;
  if (len > free_space)
  {
    usart3_tx_drop_count += (uint32_t)(len - free_space);
    write_len = free_space;
  }
  if (write_len > 0U)
  {
    usart3_ring_push_bytes(data, write_len);
  }
  usart_exit_critical();
  return (int)write_len;
}

void USART3_send_byte(unsigned char data)
{
  (void)USART3_write((const uint8_t *)&data, 1U);
}

